import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const p=JSON.parse('{"title":"How to use this documentation?","description":"","frontmatter":{},"headers":[],"relativePath":"install/usethedoc.md","filePath":"install/usethedoc.md"}'),i={name:"install/usethedoc.md"};function n(s,e,l,h,u,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<p>This documentation is based on the <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">latest Nightly Build</a> (allow a few days&#39; latency after release).</p><h2 id="if-youre-completely-new-to-xdrip" tabindex="-1"><strong>If you&#39;re completely new to xDrip</strong> <a class="header-anchor" href="#if-youre-completely-new-to-xdrip" aria-label="Permalink to &quot;**If you&#39;re completely new to xDrip**&quot;">​</a></h2><p>If you want to install it for the first time, continue to ⇒ <a href="./prerequisites.html">prerequisites</a> and follow the flow.</p><h2 id="if-youre-already-using-xdrip" tabindex="-1"><strong>If you&#39;re already using xDrip</strong> <a class="header-anchor" href="#if-youre-already-using-xdrip" aria-label="Permalink to &quot;**If you&#39;re already using xDrip**&quot;">​</a></h2><p>If you don&#39;t find a feature documented here and want it, you might need to <a href="./../use/update.html">update</a> your xDrip app.<br> See at the bottom of each page the version at which it was written; if you have an older version it might not include the feature.</p><br><div class="info custom-block"><p class="custom-block-title">Info</p><p>Engineering mode features are intentionally not documented.</p></div><br><h3 id="original-documentation" tabindex="-1">Original documentation <a class="header-anchor" href="#original-documentation" aria-label="Permalink to &quot;Original documentation&quot;">​</a></h3><p>This documentation is a collection of various sources; when applicable you will find links to the <strong>original and reference documentation</strong>.<br> Always rely on the original documentation unless obsolete (will be mentioned).</p><h3 id="translation" tabindex="-1">Translation <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Translation&quot;">​</a></h3><p>The documentation is available in English, French and Italian. Use the language selector at the top of the page to switch; you will stay on the same page.<br> Translations are in progress: pages not yet translated are shown in English, with a notice. English is the reference version; a translated page whose English version has changed since is marked as such.</p><p>For other languages, you might find it easier to follow if you <a href="./../use/display.html#language">switch your xDrip to English</a> and read it using an automatic translation with Google.</p><p>Most menu pictures have been changed to text to allow automatic translation; this means they might not match the display but hopefully they will point you to the right item.</p><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>You can search the documentation for a menu or a term using the upper right search lens feature, in the language you are reading.</p><h3 id="typo-error-missing-information" tabindex="-1">Typo, error, missing information <a class="header-anchor" href="#typo-error-missing-information" aria-label="Permalink to &quot;Typo, error, missing information&quot;">​</a></h3><p>You&#39;re welcome to give feedback by opening an <a href="https://github.com/xdrip/xdrip_docs/issues" target="_blank" rel="noreferrer">issue</a> in GitHub.</p><p>You&#39;re welcome to contribute by creating a <a href="https://github.com/xdrip/xdrip_docs/pulls" target="_blank" rel="noreferrer">pull request</a> in the main repository.</p><p>You can also give feedback in the main Facebook group <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">xDrip</a> (GitHub recommended though).</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer"><em>Last modified now</em></a></p>',22)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
